// src/modules/groups/groups.module.ts

import { FastifyPluginAsync } from 'fastify';
import groupsRoutes from './groups.routes';
import groupsInsightsRoutes from './groups.insights.routes';
import groupsClosureRoutes from './groups-closure.routes';
import groupsStateHistoryRoutes from './groups-state-history.routes';
import votesRoutes from './votes.routes';
import multipart from '@fastify/multipart';

const groupsModule: FastifyPluginAsync = async (fastify) => {
  // Registrar multipart para upload de imagens
  await fastify.register(multipart, {
    limits: {
      fileSize: 10 * 1024 * 1024, // 10MB max
      files: 1,
    },
  });

  await fastify.register(groupsRoutes);
  await fastify.register(groupsInsightsRoutes, { prefix: '/insights' });
  await fastify.register(groupsClosureRoutes);
  await fastify.register(groupsStateHistoryRoutes);
  await fastify.register(votesRoutes);
};

export default groupsModule;
export { groupsModule };












